import {readFileSync,readdirSync,writeFileSync} from 'node:fs';
const entries=readdirSync('data/holidays').filter(f=>f.endsWith('.json')).sort()
    .map(f=>JSON.parse(readFileSync(`data/holidays/${f}`,'utf8'))).filter(d=>d.verification==='official');
for (const d of entries) {
    if (d.mode!=='replace' || !Number.isInteger(d.year) || !d.scope || !d.source || !d.verifiedOn) throw Error(`Incomplete official metadata: ${d.region} ${d.year}`);
}
const header='// Generated by scripts/gen-official-bundle.mjs; reviewed official annual datasets only.\n';
writeFileSync('lib/holiday/official-data.ts',header+'export const OFFICIAL_DATA: string = '+JSON.stringify(JSON.stringify(entries))+';\n');
console.log(`Official runtime bundle: ${entries.length} reviewed annual datasets`);
